function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments need the same length.';
  if (operations[0] !== 'NumMatrix' || !Array.isArray(args[0]) || args[0].length !== 1 || !Array.isArray(args[0][0])) return 'Start with NumMatrix and one grid matrix.';
  const matrix = args[0][0];
  const m = matrix.length;
  if (m < 1 || m > 200) return 'matrix needs 1 to 200 rows.';
  if (!Array.isArray(matrix[0])) return 'Each row of matrix is a list of numbers.';
  const n = matrix[0].length;
  if (n < 1 || n > 200) return 'matrix needs 1 to 200 columns.';
  for (const line of matrix) {
    if (!Array.isArray(line) || line.length !== n) return 'Every row of matrix has the same length.';
    if (line.some(v => !Number.isInteger(v) || v < -1000 || v > 1000)) return 'Each cell is a whole number from -1000 to 1000.';
  }
  if (operations.length - 1 > 5000) return 'At most 5000 calls to update and sumRegion.';
  for (let i = 1; i < operations.length; i++) {
    const call = args[i];
    if (!Array.isArray(call) || call.some(v => !Number.isInteger(v))) return 'Each call takes whole numbers.';
    if (operations[i] === 'update') {
      const [row, col, val] = call;
      if (call.length !== 3) return 'update takes row, col and val.';
      if (row < 0 || row >= m || col < 0 || col >= n) return 'update needs a cell inside the grid.';
      if (val < -1000 || val > 1000) return 'update needs val from -1000 to 1000.';
    } else if (operations[i] === 'sumRegion') {
      const [row1, col1, row2, col2] = call;
      if (call.length !== 4) return 'sumRegion takes row1, col1, row2 and col2.';
      if (row1 < 0 || row1 > row2 || row2 >= m) return 'sumRegion needs 0 <= row1 <= row2 < m.';
      if (col1 < 0 || col1 > col2 || col2 >= n) return 'sumRegion needs 0 <= col1 <= col2 < n.';
    } else return 'Only update and sumRegion can follow the constructor.';
  }
  return null;
}

