class NumMatrix {
  constructor(matrix) {
    this.rows = matrix.length;
    this.cols = matrix[0].length;
    this.values = Array.from({ length: this.rows }, () => new Array(this.cols).fill(0));
    this.tree = Array.from({ length: this.rows + 1 }, () => new Array(this.cols + 1).fill(0));
    for (let r = 0; r < this.rows; r++) {
      for (let c = 0; c < this.cols; c++) {
        this.update(r, c, matrix[r][c]);
      }
    }
  }

  update(row, col, val) {
    const delta = val - this.values[row][col];
    this.values[row][col] = val;
    for (let i = row + 1; i <= this.rows; i += i & -i) {
      for (let j = col + 1; j <= this.cols; j += j & -j) {
        this.tree[i][j] += delta;
      }
    }
  }

  prefix(row, col) {
    let sum = 0;
    for (let i = row; i > 0; i -= i & -i) {
      for (let j = col; j > 0; j -= j & -j) {
        sum += this.tree[i][j];
      }
    }
    return sum;
  }

  sumRegion(row1, col1, row2, col2) {
    const whole = this.prefix(row2 + 1, col2 + 1);
    const above = this.prefix(row1, col2 + 1);
    const left = this.prefix(row2 + 1, col1);
    const corner = this.prefix(row1, col1);
    return whole - above - left + corner;
  }
}

