class NumMatrix {
  constructor(matrix) {
    this.grid = matrix.map(line => line.slice());
  }
  update(row, col, val) {
    this.grid[row][col] = val;
  }
  sumRegion(row1, col1, row2, col2) {
    let total = 0;
    for (let r = row1; r <= row2; r++) for (let c = col1; c <= col2; c++) total += this.grid[r][c];
    return total;
  }
}

