function generate(rand, size) {
  const rows = size === 'large' ? 100 : 1 + Math.floor(rand() * 4);
  const cols = size === 'large' ? 100 : 1 + Math.floor(rand() * 4);
  const calls = size === 'large' ? 499 : 1 + Math.floor(rand() * 12);
  const span = size === 'large' || rand() < 0.5 ? 1000 : 3;
  const value = () => Math.floor(rand() * (2 * span + 1)) - span;
  const matrix = Array.from({ length: rows }, () => Array.from({ length: cols }, value));
  const operations = ['NumMatrix'];
  const args = [[matrix]];
  const updateRate = 0.2 + rand() * 0.6;
  for (let i = 0; i < calls; i++) {
    if (rand() < updateRate) {
      operations.push('update');
      args.push([Math.floor(rand() * rows), Math.floor(rand() * cols), value()]);
    } else {
      const r1 = Math.floor(rand() * rows), r2 = Math.floor(rand() * rows);
      const c1 = Math.floor(rand() * cols), c2 = Math.floor(rand() * cols);
      operations.push('sumRegion');
      args.push([Math.min(r1, r2), Math.min(c1, c2), Math.max(r1, r2), Math.max(c1, c2)]);
    }
  }
  return [operations, args];
}
